using CondoManager.Application;
using CondoManager.Domain;
using Microsoft.EntityFrameworkCore;
namespace CondoManager.Infrastructure;
public sealed partial class AccountingService
{
 private static SettlementDto SettlementResult(StatementSettlement b)=>new(b.Id,b.StatementId,b.AccountingPeriodId,b.Date,b.JournalEntryId,b.PostedAt,b.ReversedJournalId,FRead<SettlementPreview>(b.SnapshotJson));
 private async Task<SettlementPreview> BuildSettlement(Guid condo,FinalStatement s,DateOnly date,CancellationToken ct)
 {
  await Period(condo,s.AccountingPeriodId,date,ct);if(s.Status!=FinalStatementStatus.Approved)throw new InvalidOperationException("Consuntivo non approvato.");var live=await BuildFinal(condo,FRead<FinalInput>(s.InputJson),ct,true);EnsureFinalValid(s,live);var anomalies=live.Anomalies.ToList();if(await db.StatementSettlements.AnyAsync(b=>b.CondominiumId==condo && b.AccountingPeriodId==s.AccountingPeriodId && b.PostedAt!=null && b.ReversedJournalId==null,ct))anomalies.Add(new("AlreadyPosted","Conguaglio gia contabilizzato: stornare esplicitamente prima di una nuova operazione.",true));
  var facts=await ResidentFacts(condo,ct);var ledger=await db.JournalEntryLines.Where(l=>l.CondominiumId==condo && db.Accounts.Any(a=>a.Id==l.AccountId && a.Purpose==AccountPurpose.ResidentReceivables)).SumAsync(l=>l.Debit-l.Credit,ct);if(ledger!=facts.Sum(f=>f.Amount))anomalies.Add(new("IndividualLedgerMismatch","Saldi analitici non riconciliati col giornale.",true));var delta=live.Positions.Sum(p=>p.PostingDelta);return new(s.Id,date,FHash(new{Source=s.SourceFingerprint,Date=date,Facts=facts,Ledger=ledger}),delta,ledger+delta,ledger,live.Positions,anomalies);
 }
 public async Task<SettlementPreview> PreviewSettlement(Guid condo,Guid id,DateOnly date,CancellationToken ct){await Condo(condo,ct);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead,ct);var r=await BuildSettlement(condo,await Statement(condo,id,ct),date,ct);await tx.CommitAsync(ct);return r;}
 public Task<SettlementDto> ConfirmSettlement(Guid condo,Guid id,SettlementConfirm input,CancellationToken ct)=>Write(condo,async()=>{current.RequireAdmin();var hash=FHash(new{Statement=id,Input=input});var old=await db.StatementSettlements.SingleOrDefaultAsync(b=>b.CondominiumId==condo && b.RequestId==input.RequestId,ct);if(old!=null){if(old.RequestHash!=hash)throw new InvalidOperationException("Chiave riutilizzata.");return SettlementResult(old);}var s=await Statement(condo,id,ct);var preview=await BuildSettlement(condo,s,input.Date,ct);if(preview.Fingerprint!=input.Fingerprint || preview.Anomalies.Any(a=>a.Blocking))throw new InvalidOperationException("Anteprima non valida o fonti finanziarie cambiate: ripetere la simulazione.");var b=new StatementSettlement(TenantId,condo,id,s.AccountingPeriodId,input.Date,input.RequestId,hash,FJson(preview),preview.Fingerprint,current.UserId!.Value);db.Add(b);db.AddRange(preview.Positions.Select(p=>new SettlementPosition(TenantId,condo,b.Id,p.PropertyUnitId,p.PersonId,p.UnitCode,p.PersonName,p.PostingDelta)));Audit("Final.SettlementConfirmed",b.Id);return SettlementResult(b);},ct);
 private async Task<JournalEntry?> ResidentSignedJournal(Guid condo,AccountingPeriod period,DateOnly date,Guid request,string hash,JournalKind kind,string description,IReadOnlyList<(decimal Amount,Guid Unit,Guid Person)> positions,AccountPurpose offset,CancellationToken ct)
 {
  if(positions.All(p=>p.Amount==0))return null;await EnsureResidentControls(condo,ct);var receivables=await Control(condo,AccountPurpose.ResidentReceivables,ct);var equity=await Control(condo,offset,ct);var journal=new JournalEntry(TenantId,condo,period,date,description,null,request,hash,kind);foreach(var p in positions.Where(p=>p.Amount!=0)){var amount=Math.Abs(p.Amount);journal.AddLine(receivables,p.Amount>0?amount:0,p.Amount<0?amount:0);journal.AddLine(equity,p.Amount<0?amount:0,p.Amount>0?amount:0);}journal.Post();db.Add(journal);Audit("Accounting."+kind+"Posted",journal.Id);return journal;
 }
 public Task<SettlementDto> PostSettlement(Guid condo,Guid id,CancellationToken ct)=>Write(condo,async()=>{current.RequireAdmin();var b=await db.StatementSettlements.SingleOrDefaultAsync(b=>b.Id==id && b.CondominiumId==condo,ct)??throw new NotFoundException();if(b.PostedAt.HasValue)return SettlementResult(b);var s=await Statement(condo,b.StatementId,ct);var live=await BuildSettlement(condo,s,b.Date,ct);if(live.Fingerprint!=b.Fingerprint || live.Anomalies.Any(a=>a.Blocking))throw new InvalidOperationException("Fonti cambiate dopo la conferma: creare una nuova conferma.");var period=await Period(condo,b.AccountingPeriodId,b.Date,ct);var rows=await db.SettlementPositions.Where(p=>p.SettlementId==id).OrderBy(p=>p.Id).ToListAsync(ct);var journal=await ResidentSignedJournal(condo,period,b.Date,b.RequestId,b.RequestHash,JournalKind.FinalAdjustment,"Conguaglio consuntivo v"+s.Version,rows.Select(p=>(p.Amount,p.PropertyUnitId,p.PersonId)).ToArray(),AccountPurpose.BudgetContributions,ct);b.Post(journal?.Id,current.UserId!.Value);Audit("Final.SettlementPosted",id);return SettlementResult(b);},ct);
 public Task<SettlementDto> ReverseSettlement(Guid condo,Guid id,ReversalInput input,CancellationToken ct)=>Write(condo,async()=>{current.RequireAdmin();var b=await db.StatementSettlements.SingleOrDefaultAsync(b=>b.Id==id && b.CondominiumId==condo,ct)??throw new NotFoundException();var hash=FHash(new{Operation="ReverseFinal",Settlement=id,Input=input});var retry=await Retry(condo,input.RequestId,hash,ct);if(retry!=null)return SettlementResult(b);if(input.AccountingPeriodId!=b.AccountingPeriodId)throw new InvalidOperationException("Rettificare prima della chiusura nello stesso esercizio; nessuna riapertura automatica.");var period=await Period(condo,input.AccountingPeriodId,input.Date,ct);if(b.JournalEntryId==null || b.ReversedJournalId!=null || input.Date<b.Date)throw new InvalidOperationException("Conguaglio non stornabile.");var original=await db.JournalEntries.Include(j=>j.Lines).SingleAsync(j=>j.Id==b.JournalEntryId,ct);var journal=new JournalEntry(TenantId,condo,period,input.Date,Guard.Text(input.Reason),null,input.RequestId,hash,JournalKind.Reversal,null,original.Id);foreach(var line in original.Lines)journal.AddLine(await LedgerAccount(condo,line.AccountId,ct),line.Credit,line.Debit);journal.Post();db.Add(journal);b.Reverse(journal.Id);Audit("Final.SettlementReversed",id);return SettlementResult(b);},ct);
 public async Task<IReadOnlyList<SettlementDto>> Settlements(Guid condo,Guid? period,CancellationToken ct){await Condo(condo,ct);return (await db.StatementSettlements.Where(b=>b.CondominiumId==condo && (!period.HasValue || b.AccountingPeriodId==period)).OrderByDescending(b=>b.CreatedAt).ToListAsync(ct)).Select(SettlementResult).ToArray();}
 private async Task<OpeningDto> OpeningResult(ResidentOpening o,CancellationToken ct)=>new(o.Id,o.AccountingPeriodId,o.Mode,o.SourceClosureId,o.JournalEntryId,o.Reason,(await db.OpeningPositions.Where(p=>p.OpeningId==o.Id).OrderBy(p=>p.PropertyUnitId).ThenBy(p=>p.PersonId).ToListAsync(ct)).Select(p=>new FinancialPosition(p.PropertyUnitId,p.UnitCode,p.PersonId,p.PersonName,p.Amount)).ToArray());
 public async Task<OpeningDto?> GetOpening(Guid condo,Guid period,CancellationToken ct){await Condo(condo,ct);await FinalPeriod(condo,period,ct,false);var o=await db.ResidentOpenings.SingleOrDefaultAsync(o=>o.CondominiumId==condo && o.AccountingPeriodId==period,ct);return o==null?null:await OpeningResult(o,ct);}
 public Task<OpeningDto> SetOpening(Guid condo,Guid periodId,OpeningInput input,CancellationToken ct)=>Write(condo,async()=>{
  current.RequireAdmin();Guard.Id(input.RequestId);Guard.EnumValue(input.Mode);var hash=FHash(input);var old=await db.ResidentOpenings.SingleOrDefaultAsync(o=>o.CondominiumId==condo && o.AccountingPeriodId==periodId,ct);if(old!=null){if(old.RequestId!=input.RequestId || old.RequestHash!=hash)throw new InvalidOperationException("Saldo iniziale gia verificato: nessuna sovrascrittura o secondo riporto.");return await OpeningResult(old,ct);}var period=await FinalPeriod(condo,periodId,ct);var previous=await db.AccountingPeriods.Where(p=>p.CondominiumId==condo && p.EndsOn<period.StartsOn).OrderByDescending(p=>p.EndsOn).FirstOrDefaultAsync(ct);var positions=new List<FinancialPosition>();AdministrativeClosure? source=null;
  if(input.Mode!=OpeningMode.CarryForward){var legacy=await db.Accounts.Where(a=>a.CondominiumId==condo && a.Type==AccountType.Asset && a.Purpose==AccountPurpose.General && !db.FinancialAccounts.Any(f=>f.AccountId==a.Id)).Select(a=>a.Id).ToArrayAsync(ct);var balances=await db.JournalEntryLines.Where(l=>legacy.Contains(l.AccountId)).GroupBy(l=>l.AccountId).Select(g=>g.Sum(l=>l.Debit-l.Credit)).ToArrayAsync(ct);if(balances.Any(b=>b!=0))throw new InvalidOperationException("Attivita patrimoniali pregresse non classificate: verificare o riclassificare prima di importare saldi individuali per evitare duplicazioni.");}
  if(input.Mode==OpeningMode.CarryForward){if(previous==null || previous.Status!=AccountingPeriodStatus.Closed)throw new InvalidOperationException("Chiudere amministrativamente l'esercizio precedente.");source=await db.AdministrativeClosures.SingleOrDefaultAsync(c=>c.Id==input.SourceClosureId && c.AccountingPeriodId==previous.Id && c.CondominiumId==condo,ct)??throw new NotFoundException();positions.AddRange(FRead<ClosureReview>(source.SnapshotJson).Positions);if(input.Positions?.Count>0)throw new ArgumentException("Non alterare le quote del riporto.");}
  else{if(previous!=null || input.SourceClosureId!=null)throw new InvalidOperationException("Un esercizio precedente richiede un riporto dalla sua chiusura, non un nuovo saldo libero.");if(input.Mode==OpeningMode.VerifiedZero && input.Positions?.Count>0)throw new ArgumentException("Zero verificato senza posizioni.");if(input.Mode==OpeningMode.Import){if(input.Positions==null || input.Positions.Count is <1 or >2000 || input.Positions.Select(p=>(p.PropertyUnitId,p.PersonId)).Distinct().Count()!=input.Positions.Count)throw new ArgumentException("Posizioni iniziali univoche richieste.");foreach(var row in input.Positions){var unit=await db.PropertyUnits.SingleOrDefaultAsync(u=>u.Id==row.PropertyUnitId && u.CondominiumId==condo,ct)??throw new NotFoundException();var person=await db.People.SingleOrDefaultAsync(p=>p.Id==row.PersonId,ct)??throw new NotFoundException();if(!await db.OwnershipPeriods.AnyAsync(a=>a.PropertyUnitId==unit.Id && a.PersonId==person.Id,ct))throw new ArgumentException("Saldo iniziale senza associazione storica del soggetto all'unita.");positions.Add(new(unit.Id,unit.Code,person.Id,person.DisplayName,Money.Validate(row.Amount,true)));}}}
  var journal=input.Mode==OpeningMode.Import?await ResidentSignedJournal(condo,period,period.StartsOn,input.RequestId,hash,JournalKind.ResidentOpening,"Saldi iniziali residenti",positions.Select(p=>(p.Balance,p.PropertyUnitId,p.PersonId)).ToArray(),AccountPurpose.OpeningEquity,ct):null;
  var opening=new ResidentOpening(TenantId,condo,periodId,input.Mode,source?.Id,journal?.Id,input.RequestId,hash,current.UserId!.Value,input.Reason,FJson(new{Positions=positions,Source=source==null?null:new{source.Id,source.AccountingPeriodId,source.StatementId,source.CreatedAt,Fingerprint=FRead<ClosureReview>(source.SnapshotJson).Fingerprint}}));db.Add(opening);db.AddRange(positions.Select(p=>new OpeningPosition(TenantId,condo,opening.Id,p.PropertyUnitId,p.PersonId,p.UnitCode,p.PersonName,p.Balance)));Audit("Final.OpeningVerified",opening.Id);await db.SaveChangesAsync(ct);return await OpeningResult(opening,ct);
 },ct);
 private async Task<ClosureReview> BuildClosure(Guid condo,Guid periodId,CancellationToken ct)
 {
  var period=await FinalPeriod(condo,periodId,ct);var checks=new List<StatementAnomaly>();var statement=await db.FinalStatementRows.SingleOrDefaultAsync(s=>s.CondominiumId==condo && s.AccountingPeriodId==periodId && s.Status==FinalStatementStatus.Approved,ct);FinalPreview? live=null;
  if(statement==null)checks.Add(new("FinalNotApproved","Consuntivo corrente non approvato.",true));else{live=await BuildFinal(condo,FRead<FinalInput>(statement.InputJson),ct,true);checks.AddRange(live.Anomalies);if(live.Fingerprint!=statement.SourceFingerprint)checks.Add(new("SourcesChanged","Fonti cambiate dopo lo snapshot approvato.",true));}
  var settlement=await db.StatementSettlements.SingleOrDefaultAsync(b=>b.CondominiumId==condo && b.AccountingPeriodId==periodId && b.PostedAt!=null && b.ReversedJournalId==null,ct);if(settlement==null || settlement.StatementId!=statement?.Id)checks.Add(new("SettlementNotPosted","Conguagli del consuntivo corrente non contabilizzati.",true));
  var facts=await ResidentFacts(condo,ct);var positions=GroupFacts(facts);var ledger=await db.JournalEntryLines.Where(l=>l.CondominiumId==condo && db.Accounts.Any(a=>a.Id==l.AccountId && a.Purpose==AccountPurpose.ResidentReceivables)).SumAsync(l=>l.Debit-l.Credit,ct);if(ledger!=positions.Sum(p=>p.Balance))checks.Add(new("ResidentLedgerDifference","Saldi individuali diversi dal controllo del giornale.",true));if(live!=null && live.Positions.Sum(p=>p.FinancialBalance)!=positions.Sum(p=>p.Balance))checks.Add(new("FinalBalanceDifference","Saldi finali del consuntivo non riconciliati.",true));
  var journals=await db.JournalEntries.Include(j=>j.Lines).Where(j=>j.CondominiumId==condo).OrderBy(j=>j.Id).ToListAsync(ct);var periods=await db.AccountingPeriods.Where(p=>p.CondominiumId==condo).ToDictionaryAsync(p=>p.Id,ct);if(journals.Any(j=>j.Lines.Sum(l=>l.Debit)!=j.Lines.Sum(l=>l.Credit)))checks.Add(new("JournalUnbalanced","Giornale non bilanciato.",true));if(journals.Any(j=>periods[j.AccountingPeriodId].StartsOn>period.EndsOn))checks.Add(new("FutureResidentMovements","Operazioni individuali di esercizi successivi: chiudere gli esercizi in ordine senza inglobare movimenti futuri.",true));
  if(await db.ExpenseDocuments.AnyAsync(e=>e.CondominiumId==condo && e.AccountingPeriodId==periodId && !e.IsRegistered && !e.IsCancelled,ct))checks.Add(new("DraftExpenses","Documenti di spesa ancora in bozza: contabilizzare o annullare esplicitamente.",true));
  var unmatched=await db.ResidentReceiptRows.CountAsync(r=>r.CondominiumId==condo && r.AccountingPeriodId==periodId && !db.ReceiptBankLinks.Any(l=>l.ReceiptId==r.Id && l.Status==ReceiptMatchStatus.Reconciled),ct);if(unmatched>0)checks.Add(new("UnmatchedReceipts","Incassi segnalati/associati non riconciliati: non inclusi fra i pagamenti attribuiti.",false));
  var available=await db.JournalEntries.CountAsync(j=>j.CondominiumId==condo && j.AccountingPeriodId==periodId && j.Kind==JournalKind.Receipt && !db.ReceiptBankLinks.Any(l=>l.JournalEntryId==j.Id) && !db.JournalEntries.Any(r=>r.ReversesEntryId==j.Id),ct);if(available>0)checks.Add(new("UnclaimedBankReceipts","Movimenti di incasso bancario non acquisiti: conservati nel transitorio, nessun blocco indiscriminato.",false));
  if(positions.Any(p=>p.Balance>0))checks.Add(new("OutstandingReceivables","Insoluti conservati come crediti riportabili; non impediscono la chiusura.",false));
  var banks=await FinancialAccounts(condo,ct);var evidence=FJson(new{Facts=facts,Journals=journals.Select(j=>new{j.Id,j.AccountingPeriodId,j.Date,j.Kind,j.ReversesEntryId,Lines=j.Lines.Select(l=>new{l.AccountId,l.Debit,l.Credit}).ToArray()}).ToArray(),Banks=banks,Final=live,ApprovedSnapshot=statement?.SnapshotJson});var fingerprint=FHash(new{Period=periodId,Statement=statement?.Id,Settlement=settlement?.Id,Evidence=evidence,Checks=checks});return new(periodId,statement?.Id,fingerprint,!checks.Any(c=>c.Blocking),checks,positions,ledger,positions.Sum(p=>p.Balance),evidence);
 }
 public async Task<ClosureReview> ReviewClosure(Guid condo,Guid period,CancellationToken ct){await Condo(condo,ct);var closed=await db.AdministrativeClosures.SingleOrDefaultAsync(c=>c.CondominiumId==condo && c.AccountingPeriodId==period,ct);if(closed!=null)return FRead<ClosureReview>(closed.SnapshotJson);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead,ct);var result=await BuildClosure(condo,period,ct);await tx.CommitAsync(ct);return result;}
 private static ClosureDto ClosureResult(AdministrativeClosure c)=>new(c.Id,c.AccountingPeriodId,c.StatementId,c.ClosedBy,c.CreatedAt,FRead<ClosureReview>(c.SnapshotJson));
 public Task<ClosureDto> CloseAdministration(Guid condo,Guid periodId,CloseInput input,CancellationToken ct)=>Write(condo,async()=>{current.RequireAdmin();Guard.Id(input.RequestId);var hash=FHash(input);var old=await db.AdministrativeClosures.SingleOrDefaultAsync(c=>c.CondominiumId==condo && c.AccountingPeriodId==periodId,ct);if(old!=null){if(old.RequestId!=input.RequestId || old.RequestHash!=hash)throw new InvalidOperationException("Esercizio gia chiuso con un'altra operazione.");return ClosureResult(old);}var review=await BuildClosure(condo,periodId,ct);if(!review.CanClose || review.Fingerprint!=input.Fingerprint)throw new InvalidOperationException("Checklist non valida o fonti cambiate: ripetere la verifica.");var period=await FinalPeriod(condo,periodId,ct);var row=new AdministrativeClosure(TenantId,condo,periodId,review.StatementId!.Value,input.RequestId,hash,current.UserId!.Value,FJson(review));db.Add(row);period.Close();Audit("Final.PeriodClosed",row.Id);return ClosureResult(row);},ct);
 public async Task<IReadOnlyList<ClosureDto>> Closures(Guid condo,CancellationToken ct){await Condo(condo,ct);return (await db.AdministrativeClosures.Where(c=>c.CondominiumId==condo).OrderByDescending(c=>c.CreatedAt).ToListAsync(ct)).Select(ClosureResult).ToArray();}
}
